// ② First-time / unlinked Telegram account: ask for the employee code (no LLM).
// Decision 2026-10-20: link by employee code only (no birth date) for now.
const b = $('Input').first().json;
const toLatin = (s) => String(s || '')
  .replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
  .replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const cm = toLatin(b.user_text).match(/NXR\s*-?\s*(\d{3,5})/i);
const code = cm ? `NXR-${cm[1].padStart(4, '0')}` : null;
if (code) return [{ json: { action: 'link', code, chat_id: b.chat_id } }];
return [{ json: { action: 'ask', route: 'onboarding',
  output: 'أهلاً بحضرتك 👋 أنا نور، مساعد موظفين Nexora Digital Solutions.\nقبل ما أساعد حضرتك ابعتلي كود الموظف بتاعك، مثلاً: NXR-1001\nلو مش عارف الكود، تلاقيه في سيستم الـ HR أو اسأل الموارد البشرية.',
  tool_calls: [{ tool: 'onboarding', input: { has_code: false }, output: null }] } }];

// Turns hr.link_telegram_by_code's result into a reply. No LLM.
const r = $json.result || {};
const first = String(r.name || '').split(' ')[0];
const left = Number.isFinite(r.attempts_left) ? ` (فاضل ${r.attempts_left} محاولات)` : '';
const MAP = {
  linked: `تمام يا ${first}، اتربط حساب حضرتك ✅\nدلوقتي تقدر تسألني عن اللائحة، أو رصيد أجازاتك وطلباتك وحضورك، أو تقدملي طلب أجازة أو إذن أو مأمورية أو خطاب. حضرتك محتاج إيه؟`,
  already_linked: 'حساب حضرتك مربوط بالفعل ✅ اتفضل اسألني.',
  invalid: `كود الموظف ده مش موجود عندنا 🙏 راجعه وابعته تاني${left}.`,
  too_many_attempts: 'محاولات كتير غلط 🙏 جرب تاني بعد ساعة أو تواصل مع الموارد البشرية.',
  linked_elsewhere: 'كود الموظف ده مربوط بحساب تليجرام تاني 🙏 لو ده حسابك الجديد تواصل مع الموارد البشرية عشان يفكوا الربط القديم.',
};
return [{ json: {
  output: MAP[r.result] ?? 'معلش، حصلت مشكلة في التحقق 🙏 جرب تاني بعد شوية.',
  route: 'onboarding',
  tool_calls: [{ tool: 'link_telegram', input: { code: $('Onboarding Step').first().json.code }, output: { result: r.result ?? 'error' } }],
} }];

// Onboarding result → CONTRACT (what the main workflow's Prepare Reply expects).
const b = $('Input').first().json;
return [{ json: { update_id: b.update_id, chat_id: b.chat_id, route: 'onboarding',
  output: String($json.output ?? '').trim(), tool_calls: Array.isArray($json.tool_calls) ? $json.tool_calls : [],
  router: { decided_by: 'onboarding', pass: null, model: null, error: null }, faq: null } }];
